export type DiagramSource =
  | { kind: 'file'; path: string; entry?: string }
  | { kind: SourceWord };

export interface DiagramReview {
  /** The diagram, or null when a problem refuses it. */
  diagram: DiagramFileV1 | null;
  /** Why the file is refused. */
  problems: string[];
  /** What the file keeps but should fix. */
  warnings: string[];
}

export type DiagramMetadata = NonNullable<NonNullable<Artifact['metadata']>['diagram']>;

/** metadata.diagram for a diagram the review kept: what the Outputs list shows without reading the file. */
export function diagramMetadata(diagram: DiagramFileV1, warnings: string[], savedByUser = false): DiagramMetadata {
  return {
    kind: diagram.kind,
    ...(diagram.kind === 'process_flow' && diagram.platform ? { platform: diagram.platform } : {}),
    title: diagram.title,
    summary: diagram.summary,
    // A process flow counts its nodes and flows here.
    entityCount: diagram.kind === 'data_model' ? diagram.entities.length : diagram.nodes.length,
    relationshipCount: diagram.kind === 'data_model' ? diagram.relationships.length : diagram.flows.length,
    ...(warnings.length > 0 ? { warnings } : {}),
    ...(savedByUser ? { savedByUser: true } : {}),
  };
}

/** The file's text for a diagram the app writes (a hand save): indented, so it reads as a file. */
export function diagramFileText(diagram: DiagramFileV1): string {
  return `${JSON.stringify(diagram, null, 2)}\n`;
}

/** `base`, or the first `base_2`, `base_3`… not taken. A Salesforce `__c` name keeps its suffix. */
export function uniqueName(taken: Iterable<string>, base: string): string {
  const used = new Set(taken);
  if (!used.has(base)) return base;
  const custom = base.match(/^(.*?)(__c)$/i);
  for (let n = 2; ; n += 1) {
    const candidate = custom ? `${custom[1]}_${n}${custom[2]}` : `${base}_${n}`;
    if (!used.has(candidate)) return candidate;
  }
}

/** Whether this /output path is a diagram file (`<name>.diagram.json`). */
export function isDiagramFilename(filename: string): boolean {
  const base = filename.slice(filename.lastIndexOf('/') + 1).toLowerCase();
  return base.length > DIAGRAM_FILE_SUFFIX.length && base.endsWith(DIAGRAM_FILE_SUFFIX);
}

/**
 * A `source` string read: an input path with an optional `#` and the entry or
 * line inside it (`/uploads/metadata.zip#objects/…`, `/uploads/schema.sql#L42`),
 * or one of SOURCE_WORDS. Null when it's missing or neither.
 */
export function parseDiagramSource(source: string | undefined): DiagramSource | null {
  if (!source) return null;
  if ((SOURCE_WORDS as readonly string[]).includes(source)) return { kind: source as SourceWord };
  if (!source.startsWith('/') || source.length < 2) return null;
  const hash = source.indexOf('#');
  if (hash < 0) return { kind: 'file', path: source };
  const path = source.slice(0, hash);
  const entry = source.slice(hash + 1);
  return entry ? { kind: 'file', path, entry } : { kind: 'file', path };
}

/** Where a field (or, with no field, the entity) came from: a field without a source takes its entity's. */
export function sourceOf(entity: DataModelEntity, field?: DataModelField): string | undefined {
  return field?.source ?? entity.source;
}

/** The review of a diagram file's text. */
export function reviewDiagramText(text: string): DiagramReview {
  let candidate: unknown;
  try {
    candidate = JSON.parse(text);
  } catch (error) {
    return { diagram: null, problems: [`it isn't valid JSON (${error instanceof Error ? error.message : String(error)})`], warnings: [] };
  }
  return reviewDiagram(candidate);
}

/** The review of a parsed diagram file: its shape, then what the shape can't say. */
export function reviewDiagram(candidate: unknown): DiagramReview {
  const parsed = diagramFileSchema.safeParse(candidate);
  if (!parsed.success) {
    const problems = parsed.error.issues.map((issue) => `${issue.path.length > 0 ? issue.path.join('.') : '(top level)'}: ${issue.message}`);
    return { diagram: null, problems, warnings: [] };
  }
  const { problems, warnings } = parsed.data.kind === 'data_model' ? reviewDataModel(parsed.data) : reviewProcessFlow(parsed.data);
  return { diagram: problems.length > 0 ? null : parsed.data, problems, warnings };
}

/** Why a distribution's numbers can't be drawn from, or null. */
function distributionProblem(distribution: Distribution): string | null {
  if (distribution.type === 'uniform' && distribution.min > distribution.max) return 'its min is above its max';
  if (distribution.type === 'triangular' && !(distribution.min <= distribution.mode && distribution.mode <= distribution.max)) {
    return 'it needs min ≤ mode ≤ max';
  }
  return null;
}

function reviewProcessFlow(diagram: ProcessFlowDiagram): { problems: string[]; warnings: string[] } {
  const problems: string[] = [];
  const warnings: string[] = [];
  const checkSource = (source: string | undefined, where: string) => {
    if (source !== undefined && parseDiagramSource(source) === null) {
      warnings.push(`${where}: source "${source}" is neither an input path (/uploads/…) nor platform, user or assumed`);
    }
  };

  const nodes = new Map<string, FlowNode>();
  for (const node of diagram.nodes) {
    if (nodes.has(node.id)) problems.push(`two nodes have the id "${node.id}"`);
    else nodes.set(node.id, node);
    checkSource(node.source, `node "${node.id}"`);
  }
  const resources = new Set<string>();
  for (const resource of diagram.resources) {
    if (resources.has(resource.id)) problems.push(`two resources have the id "${resource.id}"`);
    resources.add(resource.id);
    checkSource(resource.source, `resource "${resource.id}"`);
  }
  const flowIds = new Set<string>();
  const outgoing = new Map<string, Flow[]>();
  const incoming = new Map<string, Flow[]>();
  for (const flow of diagram.flows) {
    if (flowIds.has(flow.id)) problems.push(`two flows have the id "${flow.id}"`);
    flowIds.add(flow.id);
    if (!nodes.has(flow.from)) problems.push(`flow "${flow.id}": from "${flow.from}" isn't a node id`);
    if (!nodes.has(flow.to)) problems.push(`flow "${flow.id}": to "${flow.to}" isn't a node id`);
    outgoing.set(flow.from, [...(outgoing.get(flow.from) ?? []), flow]);
    incoming.set(flow.to, [...(incoming.get(flow.to) ?? []), flow]);
  }

  const starts = diagram.nodes.filter((node) => node.type === 'start');
  if (starts.length === 0) problems.push('a process flow needs a start node (where work arrives)');
  if (!diagram.nodes.some((node) => node.type === 'end')) problems.push('a process flow needs an end node (where work leaves)');
  // A Salesforce flow is automation: nothing to simulate, so no numbers to ask for.
  const simulated = diagram.platform !== 'salesforce';
  if (simulated && !diagram.timeUnit) problems.push('a process flow needs a timeUnit (seconds, minutes, hours or days): the unit of its times');
  if (simulated) {
    for (const flow of diagram.flows) {
      if (flow.fault) problems.push(`flow "${flow.id}": fault flows are for Salesforce flows (platform "salesforce"); a simulated process branches with a decision`);
      if (flow.launch) problems.push(`flow "${flow.id}": launch flows are for Salesforce flows (platform "salesforce"); a simulated process branches with a decision`);
    }
  }

  for (const node of diagram.nodes) {
    const where = `node "${node.id}"`;
    const all = outgoing.get(node.id) ?? [];
    // A fault flow is where a step goes when it fails, and a launch flow what else it starts, beside its one way on.
    const out = all.filter((flow) => !flow.fault && !flow.launch);
    if (node.type !== 'step') {
      for (const flow of all) if (flow.launch) problems.push(`flow "${flow.id}": only a step starts other automation (a launch flow)`);
    }
    if (node.type === 'start') {
      if (simulated && !node.arrivals) problems.push(`${where}: a start needs arrivals, the time between arrivals`);
      // Another flow's step may start this one (a subflow, a platform event).
      if ((incoming.get(node.id) ?? []).some((flow) => !flow.launch)) problems.push(`${where}: nothing flows into a start`);
      if (all.length !== 1) problems.push(`${where}: a start has one flow out (it has ${all.length})`);
    } else if (node.type === 'step') {
      if (simulated && !node.duration) problems.push(`${where}: a step needs a duration`);
      if (out.length !== 1) problems.push(`${where}: a step has one flow out; branch with a decision node (it has ${out.length})`);
      if (node.resource !== undefined && !resources.has(node.resource)) problems.push(`${where}: resource "${node.resource}" isn't in resources`);
      if (node.resource !== undefined && node.capacity !== undefined) warnings.push(`${where}: it has a resource and a capacity; the resource's capacity is used`);
    } else if (node.type === 'decision') {
      if (out.length < 2) problems.push(`${where}: a decision has two or more flows out (it has ${out.length})`);
      const shares = out.map((flow) => flow.share);
      if (!simulated) {
        // A Salesforce decision branches on its outcomes' conditions, not on shares.
      } else if (shares.some((share) => share === undefined)) {
        problems.push(`${where}: every branch of a decision needs a share (the shares add up to 1)`);
      } else {
        const total = (shares as number[]).reduce((sum, share) => sum + share, 0);
        if (out.length > 0 && Math.abs(total - 1) > 0.01) problems.push(`${where}: its branch shares add up to ${Number(total.toFixed(3))}, not 1`);
      }
    } else if (all.length > 0) {
      problems.push(`${where}: nothing flows out of an end`);
    }
    for (const [key, distribution] of [['arrivals', node.arrivals], ['duration', node.duration]] as const) {
      const problem = distribution ? distributionProblem(distribution) : null;
      if (problem) problems.push(`${where}: ${key}: ${problem}`);
    }
    if (node.type !== 'decision') {
      for (const flow of all) if (flow.share !== undefined) warnings.push(`flow "${flow.id}": only a decision's branches have shares`);
    }
    if (!simulated && node.type === 'start') {
      for (const flow of all) if (flow.fault) problems.push(`flow "${flow.id}": a start has no fault path`);
    }
  }

  if (diagram.run?.warmup !== undefined && diagram.run.warmup >= diagram.run.duration) {
    problems.push('run: the warmup has to be shorter than the run');
  }

  // Every node is reached from a start, and every node can reach an end (or work circles forever).
  if (problems.length === 0) {
    const reach = (from: string[], next: (id: string) => string[]) => {
      const seen = new Set(from);
      for (const queue = [...from]; queue.length > 0;) {
        for (const id of next(queue.shift()!)) if (!seen.has(id)) { seen.add(id); queue.push(id); }
      }
      return seen;
    };
    const reached = reach(starts.map((node) => node.id), (id) => (outgoing.get(id) ?? []).map((flow) => flow.to));
    const finishing = reach(diagram.nodes.filter((node) => node.type === 'end').map((node) => node.id), (id) => (incoming.get(id) ?? []).map((flow) => flow.from));
    for (const node of diagram.nodes) {
      if (!reached.has(node.id)) warnings.push(`node "${node.id}": nothing reaches it from a start`);
      else if (!finishing.has(node.id)) problems.push(`node "${node.id}": no path from it reaches an end, so work that gets there never finishes`);
    }
  }
  return { problems, warnings };
}

/** The diagram, or null when the text isn't a usable diagram file. */
export function parseDiagramFile(text: string): DiagramFileV1 | null {
  return reviewDiagramText(text).diagram;
}

function isMany(cardinality: Cardinality): boolean {
  return cardinality === 'zero_or_more' || cardinality === 'one_or_more';
}

function reviewDataModel(diagram: DataModelDiagram): { problems: string[]; warnings: string[] } {
  const problems: string[] = [];
  const warnings: string[] = [];
  const checkSource = (source: string | undefined, where: string) => {
    if (source !== undefined && parseDiagramSource(source) === null) {
      warnings.push(`${where}: source "${source}" is neither an input path (/uploads/…) nor platform, user or assumed`);
    }
  };

  const entities = new Map<string, DataModelEntity>();
  for (const entity of diagram.entities) {
    if (entities.has(entity.id)) problems.push(`two entities have the id "${entity.id}"`);
    else entities.set(entity.id, entity);
    checkSource(entity.source, `entity "${entity.id}"`);
    const fieldNames = new Set<string>();
    for (const field of entity.fields) {
      if (fieldNames.has(field.name)) problems.push(`entity "${entity.id}" has two fields named "${field.name}"`);
      fieldNames.add(field.name);
      checkSource(field.source, `field "${entity.id}.${field.name}"`);
    }
    const recordTypeNames = new Set<string>();
    for (const recordType of entity.recordTypes ?? []) {
      if (recordTypeNames.has(recordType.name)) warnings.push(`entity "${entity.id}" has two record types named "${recordType.name}"`);
      recordTypeNames.add(recordType.name);
      checkSource(recordType.source, `record type "${entity.id}.${recordType.name}"`);
    }
  }

  const allowedKinds = RELATIONSHIP_KINDS_BY_PLATFORM[diagram.platform];
  const relationshipIds = new Set<string>();
  const masterDetails = new Map<string, number>();
  for (const relationship of diagram.relationships) {
    const where = `relationship "${relationship.id}"`;
    const { kind, cardinality } = relationship;
    if (relationshipIds.has(relationship.id)) problems.push(`two relationships have the id "${relationship.id}"`);
    relationshipIds.add(relationship.id);
    if (!allowedKinds.includes(kind)) {
      problems.push(`${where}: a ${diagram.platform} model has no ${kind} relationships (it has ${allowedKinds.join(', ')})`);
    }
    const from = entities.get(relationship.from);
    const to = entities.get(relationship.to);
    if (!from) problems.push(`${where}: from "${relationship.from}" isn't an entity id`);
    if (!to) problems.push(`${where}: to "${relationship.to}" isn't an entity id`);
    if (relationship.toField !== undefined && kind !== 'foreign_key') {
      problems.push(`${where}: toField is for foreign_key relationships only`);
    }

    if (kind === 'conceptual') {
      if (relationship.field !== undefined) {
        problems.push(`${where}: a conceptual relationship has no field; a relationship a field holds is ${allowedKinds.filter((k) => k !== 'conceptual').join(' or ')}`);
      }
      continue;
    }

    if (isMany(cardinality.to)) {
      problems.push(`${where}: its to end is ${cardinality.to}, but a field holds at most one "${relationship.to}"; use zero_or_one or exactly_one, or a junction entity for many-to-many`);
    }
    if (relationship.field === undefined) {
      problems.push(`${where}: a ${kind} relationship needs field, the field on "${relationship.from}" that holds it`);
      continue;
    }
    const field = from?.fields.find((candidate) => candidate.name === relationship.field);
    if (from && !field) problems.push(`${where}: "${relationship.from}" has no field "${relationship.field}"`);
    if (to && relationship.toField !== undefined && !to.fields.some((candidate) => candidate.name === relationship.toField)) {
      problems.push(`${where}: "${relationship.to}" has no field "${relationship.toField}"`);
    }

    const fieldName = `"${relationship.from}.${relationship.field}"`;
    if (kind === 'master_detail') {
      masterDetails.set(relationship.from, (masterDetails.get(relationship.from) ?? 0) + 1);
      // A master-detail field is always required, whatever its flag says.
      if (cardinality.to === 'zero_or_one') {
        warnings.push(`${where}: a master-detail's to end is exactly_one (every detail has a master), not zero_or_one`);
      }
    } else if (field && !isMany(cardinality.to)) {
      const lineRequires = cardinality.to === 'exactly_one';
      if (field.required && !lineRequires) {
        warnings.push(`${where}: ${fieldName} is required, but the to end is ${cardinality.to}; make the end exactly_one, or the field optional`);
      } else if (!field.required && lineRequires) {
        warnings.push(`${where}: the to end is exactly_one, but ${fieldName} isn't required; mark the field required, or make the end zero_or_one`);
      }
    }
    if (field?.unique && isMany(cardinality.from)) {
      warnings.push(`${where}: ${fieldName} is unique, so one "${relationship.to}" has at most one "${relationship.from}", but the from end is ${cardinality.from}; use zero_or_one or exactly_one`);
    }
  }

  if (diagram.platform === 'salesforce') {
    for (const [entityId, count] of masterDetails) {
      if (count > 2) warnings.push(`entity "${entityId}" has ${count} master-detail relationships; Salesforce allows two per object`);
    }
  }

  return { problems, warnings };
}
